for (x = x0; x <= x1; x += 8) pts.push([x, y0 + 6 * Math.sin(x / 85) + 3 * Math.sin(x / 23 + 2) + (rn(x) - 0.5) * 3]);
for (t = 0.05; t < 1; t += 0.05) pts.push([x1 + 22 * Math.sin(Math.PI * t) - 10 * t + (rn(t * 91) - 0.5) * 6, y0 + (y1 - y0) * t]);
for (x = x1; x >= x0; x -= 8) pts.push([x, y1 + 7 * Math.sin(x / 70 + 1) + 3 * Math.sin(x / 19) + (rn(x + 5) - 0.5) * 3]);
for (t = 0.95; t > 0; t -= 0.05) pts.push([x0 - 26 * Math.sin(Math.PI * t) + 12 * t + (rn(t * 57) - 0.5) * 6, y0 + (y1 - y0) * t]);
